//! The rules from rules.toml, as tables generated by build.rs.

use crate::Reason;

/// What a rule means for the level (see the header of rules.toml).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Class {
    Chain,
    Aggravator,
    Lure,
    Padding,
    Tool,
}

/// One `[[feature]]` of rules.toml.
#[derive(Debug)]
pub(crate) struct FeatureDef {
    pub id: &'static str,
    pub class: Class,
    pub reason: Reason,
    pub strong: bool,
    pub low_alone: bool,
    pub anchors: &'static [&'static str],
    pub pattern: &'static str,
}

/// One `[[installer]]` of rules.toml.
#[derive(Debug)]
pub(crate) struct InstallerDef {
    #[allow(dead_code)] // documents the entry; used by the tests
    pub name: &'static str,
    pub prefixes: &'static [&'static str],
}

include!(concat!(env!("OUT_DIR"), "/rules_gen.rs"));
